using System;using System.IO;using UnityEngine;using UnityEditor;
public static class MallViewR16Review {
 public static void Run(){var g=BuildFlight.PrepareScene();g.Initialize();g.enabled=false;var sector=Array.Find(WorldRouteR11.Data.sectors,x=>x.id=="mall");var c=g.ReviewCamera;c.orthographicSize=sector.viewSize;c.aspect=1100f/650;c.transform.rotation=Quaternion.LookRotation(new Vector3(0,-5.3f,16));var target=new Vector3(sector.viewX,sector.viewY+5.3f,-16);float bottom=target.y-c.orthographicSize*c.transform.up.y;float back=Mathf.Max(0,(.5f-bottom)/-c.transform.forward.y);c.transform.position=target-c.transform.forward*back;string dir="../evidence/mall-final";Directory.CreateDirectory(dir);var rt=new RenderTexture(1100,650,24);rt.Create();c.targetTexture=rt;RenderTexture.active=rt;c.Render();var im=new Texture2D(1100,650,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,1100,650),0,0);im.Apply();File.WriteAllBytes(dir+"/mall-ground-cases.png",im.EncodeToPNG());File.WriteAllText(dir+"/view.json",JsonUtility.ToJson(new View{source="same mall sector/camera projection, camera depth backoff only; no launch or new physics result",size=c.orthographicSize,backoff=back,position=c.transform.position,artRevision=SectionWorldArtR16.Revision},true));c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(im);rt.Release();UnityEngine.Object.DestroyImmediate(rt);g.ShutdownReviewPhysics();}
 [Serializable]class View{public string source,artRevision;public float size,backoff;public Vector3 position;}
}
